# -*- coding: utf-8 -*-
"""Residentado Médico · Lote 6, paquete 19 (psiquiatría, trastornos de la conducta alimentaria, osteoporosis, lupus y FARME)"""
from lote01a import Q
import lote01a
L = []
lote01a.L = L
KS = "Kaplan y Sadock, Sinopsis de Psiquiatría, 12.ª ed. (2021)"
DSM = "APA, DSM-5-TR (2022)"
GLAD = "GLAD-PC, tratamiento de la depresión adolescente en atención primaria (Pediatrics 2018)"
HAR = "Harrison, Principios de Medicina Interna, 21.ª ed. (2022)"
OSTEO = "Endocrine Society, manejo farmacológico de la osteoporosis posmenopáusica (J Clin Endocrinol Metab 2020)"

Q(a="psiquiatria", cat="Trastornos de personalidad", tema="Trastorno de personalidad antisocial", año=2016, ext=False,
  e="Varón de 40 años con historia personal donde prima la búsqueda de su propia satisfacción a costa del sufrimiento de los demás, sin capacidad de cambio ni culpa a pesar de las consecuencias. ¿Qué trastorno de personalidad presenta?",
  o=["Obsesivo.", "Limítrofe.", "Antisocial.", "Paranoide.", "Esquizoide."], k="C",
  c="El trastorno de personalidad antisocial pertenece al grupo B (dramático, emocional e impulsivo) y se define por un patrón persistente de desprecio y violación de los derechos de los demás que comienza en la infancia o la adolescencia. El DSM-5-TR (2022) exige edad mínima de 18 años, evidencia de trastorno de conducta antes de los 15 y tres o más criterios: incumplimiento de las normas legales, engaño y manipulación, impulsividad, irritabilidad con agresiones, desprecio imprudente por la seguridad propia o ajena, irresponsabilidad sostenida y ausencia de remordimiento. La psicopatía, medida con la escala de Hare (PCL-R), es un constructo emparentado, aunque más centrado en la frialdad afectiva. Las otras opciones no encajan: el obsesivo se caracteriza por perfeccionismo y rigidez, el limítrofe por inestabilidad afectiva, miedo al abandono y autolesiones, el paranoide por desconfianza sistemática y el esquizoide por desapego y frialdad sin intención de dañar a otros. No existe fármaco específico; el tratamiento es psicoterapéutico, de respuesta limitada, y se centra en las comorbilidades como el consumo de sustancias. Perla clínica: ante un paciente que manipula y no muestra culpa, siempre se descarta consumo de sustancias y se revisa el historial de conducta antes de los 15 años.",
  f=DSM + "; " + KS + "; " + HAR)

Q(a="psiquiatria", cat="Sustancias", tema="Intoxicación por cocaína inhalada", año=2016, ext=False,
  e="Adolescente de 15 años, es traído por presentar euforia y ansiedad. Examen: FC 120 por minuto, FR 28 por minuto, PA 160/110 mmHg, T 38 °C, ojos: midriasis bilateral. Antecedente: epistaxis y rinorrea crónica. ¿Cuál es la sustancia causante de este cuadro?",
  o=["Cocaína.", "Marihuana.", "Ácido lisérgico.", "Heroína.", "Benzodiazepinas."], k="A",
  c="La cocaína bloquea la recaptación de noradrenalina, dopamina y serotonina, de modo que produce un síndrome simpaticomimético: euforia, agitación, ansiedad, taquicardia, hipertensión, hipertermia, midriasis y sudoración. El antecedente de epistaxis y rinorrea crónica orienta a consumo por vía inhalada, que daña la mucosa nasal y puede llegar a perforar el tabique. Las complicaciones graves son el síndrome coronario agudo por vasoespasmo, arritmias, disección aórtica, accidente cerebrovascular, convulsiones, rabdomiólisis e hipertermia maligna. El tratamiento de primera línea son las benzodiazepinas para la agitación, la taquicardia y la hipertensión, con enfriamiento externo y fluidos; si persiste la hipertensión se usan vasodilatadores como nitratos o fentolamina, y se evitan los betabloqueadores sin acción alfa. La marihuana produce enrojecimiento conjuntival, boca seca, aumento del apetito y taquicardia leve sin hipertensión marcada; el ácido lisérgico se acompaña de alucinaciones y distorsiones sensoriales; la heroína causa miosis, bradipnea y depresión del sensorio, y las benzodiazepinas producen sedación, no excitación. Perla clínica: ante un joven con dolor torácico, hipertensión y midriasis, se pregunta siempre por cocaína y se solicita un electrocardiograma y troponinas.",
  f=KS + "; " + HAR + "; " + DSM)

Q(a="psiquiatria", cat="Trastornos de personalidad", tema="Trastorno de personalidad evitativa", año=2017, ext=False,
  e="Mujer de 20 años, tímida desde la niñez, presenta serios problemas de interrelación; últimamente se siente atraída por un compañero de aula, pero como se considera torpe y poco atractiva, tiene vergüenza por lo que prefiere no contestarle cada vez que le habla. ¿Qué trastorno de personalidad presenta?",
  o=["Dependiente.", "Paranoide.", "Esquizoide.", "Antisocial.", "Evitativa."], k="E",
  c="El trastorno de personalidad evitativa (grupo C, ansioso y temeroso) consiste en un patrón generalizado de inhibición social, sentimientos de inadecuación e hipersensibilidad a la evaluación negativa que se inicia en la adultez temprana. El DSM-5-TR (2022) pide cuatro de siete criterios: evita actividades laborales por miedo a la crítica, no se implica si no está segura de agradar, se muestra cohibida en las relaciones íntimas por temor a la burla, se preocupa por ser criticada, se inhibe en situaciones nuevas por sentirse inadecuada, se ve a sí misma como inepta o inferior y evita riesgos personales. La clave diagnóstica es el deseo de relacionarse que choca con el miedo al rechazo, como en esta paciente que se siente atraída pero calla. En el esquizoide no existe ese deseo, hay indiferencia afectiva; el dependiente teme la separación y necesita que lo cuiden; el paranoide desconfía y atribuye mala intención; el antisocial no siente vergüenza ni respeta las normas. Hay mucha superposición con la fobia social generalizada, y el tratamiento se basa en terapia cognitivo-conductual y entrenamiento en habilidades sociales, con ISRS cuando hay ansiedad o depresión asociadas. Perla clínica: evitativo desea afecto y huye; esquizoide no lo desea.",
  f=DSM + "; " + KS + "; " + HAR)

Q(a="psiquiatria", cat="Trastornos de ansiedad", tema="Trastorno de pánico", año=2017, ext=False,
  e="Mujer de 24 años que es traída por sus familiares porque en forma brusca presenta taquicardia, dificultad para respirar, sudoración, opresión precordial «como si me fuera a morir». Antecedente: 2 episodios similares de 30 a 50 minutos de duración. TSH, T4, enzimas cardiacas, perfil hemático y lipídico normales. ¿Cuál es el diagnóstico probable?",
  o=["Trastorno de pánico.", "Trastorno depresivo recurrente.", "Trastorno esquizoafectivo.", "Reacción al estrés grave.", "Episodio maniaco."], k="A",
  c="El trastorno de pánico se caracteriza por ataques de pánico recurrentes e inesperados: aparición abrupta de miedo intenso que alcanza su máximo en minutos y se acompaña de al menos cuatro de trece síntomas (palpitaciones, sudoración, temblor, disnea, sensación de ahogo, dolor torácico, náuseas, mareo, escalofríos, parestesias, desrealización, miedo a perder el control o a morir). Para el diagnóstico, según el DSM-5-TR (2022), después de al menos un ataque debe haber un mes o más de preocupación persistente por nuevos ataques o un cambio desadaptativo de conducta, como evitar lugares. Antes de aceptarlo se descartan causas orgánicas: hipertiroidismo, feocromocitoma, arritmias, síndrome coronario, hipoglucemia, abuso de estimulantes o abstinencia; aquí la TSH, la T4 y las enzimas cardiacas normales apoyan el origen psiquiátrico. El episodio maniaco cursa con ánimo elevado y menor necesidad de sueño durante días; el depresivo recurrente y el esquizoafectivo exigen un síndrome afectivo sostenido; la reacción al estrés grave requiere un factor estresante identificable. El tratamiento de elección combina ISRS (sertralina, escitalopram) y terapia cognitivo-conductual, y las benzodiazepinas se reservan para corto plazo. Perla clínica: la duración típica de un ataque es de 10 a 30 minutos.",
  f=DSM + "; " + KS + "; " + HAR,
  nota="La opción E está truncada por el OCR («Episodio maniaco»); la clave A coincide con el libro y con los criterios DSM-5-TR.")

Q(a="psiquiatria", cat="Violencia familiar", tema="Factor asociado a violencia familiar", año=2018, ext=False,
  e="Mujer de 25 años, consulta por ser agredida constantemente por el esposo, incluso en presencia de los hijos. El esposo procede de una familia numerosa y desde pequeño vivió solo con la madre. No pudo ir al colegio y actualmente es trabajador eventual. ¿Cuál es el factor principal asociado a la violencia en esta familia?",
  o=["Antecedente de depresión.", "Carencia de la figura paterna.", "Bajo nivel de educación.", "Antecedente de maltrato psicológico.", "Nivel social bajo."], k="B",
  c="La violencia de pareja se explica con el modelo ecológico de la OMS: confluyen factores individuales (haber presenciado o sufrido maltrato en la infancia, consumo de alcohol, rasgos de personalidad antisocial), relacionales (conflicto conyugal, control masculino de la pareja), comunitarios (pobreza, aislamiento) y sociales (normas de género desiguales). En el enunciado, el dato más destacado es la crianza del agresor sin figura paterna, y el libro lo toma como el factor principal: la ausencia de un modelo de crianza adecuado favorece la identificación con patrones de dominio y escaso control de impulsos, repetidos luego en la pareja y los hijos, lo que se conoce como transmisión intergeneracional de la violencia. El bajo nivel educativo y el nivel social bajo son factores de riesgo reales pero menos específicos, pues la violencia ocurre en todos los estratos; el antecedente de depresión y el maltrato psicológico no se mencionan en el relato. En la atención se valora el riesgo vital, se ofrece plan de seguridad, se documenta las lesiones, se deriva a servicios de protección y se brinda apoyo psicológico a la víctima y a los hijos. Perla clínica: se pregunta por violencia de forma directa y sin juicio en toda consulta de riesgo.",
  f="OMS, directrices clínicas y de políticas sobre la respuesta a la violencia de pareja y la violencia sexual contra la mujer (2013); " + KS,
  nota="Pregunta de opinión: la clave B es la del libro. La evidencia pone como factor más consistente el haber presenciado o sufrido violencia en la infancia; se mantiene B por ser la única opción coherente con el relato.")

Q(a="psiquiatria", cat="Trastornos del ánimo", tema="Depresión mayor con melancolía", año=2018, ext=False,
  e="Varón de 48 años, desde hace un mes presenta cambios de carácter, irritabilidad y dificultad para realizar actividades en el trabajo, que se acentúan durante las mañanas. Esposa refiere que está más callado, demuestra poco interés por las actividades del hogar, con melancolía, adinamia y pérdida de peso. ¿Cuál es el diagnóstico más probable?",
  o=["Trastorno distímico.", "Fobia social.", "Obsesivo compulsivo.", "Depresión mayor.", "Ansiedad generalizada."], k="D",
  c="El episodio depresivo mayor exige, según el DSM-5-TR (2022), cinco o más síntomas durante al menos dos semanas con deterioro funcional, y entre ellos ánimo deprimido o anhedonia: pérdida de interés, alteraciones del apetito o del peso, insomnio o hipersomnia, enlentecimiento o agitación, fatiga, culpa o inutilidad, dificultad de concentración y pensamientos de muerte. Este paciente reúne irritabilidad, pérdida de interés, adinamia, pérdida de peso y un patrón con empeoramiento matutino, la variación diurna típica del especificador de características melancólicas. La distimia (trastorno depresivo persistente) requiere al menos dos años de síntomas menos intensos, por eso no corresponde a un mes de evolución. La fobia social y la ansiedad generalizada se centran en miedo o preocupación y no en anhedonia y pérdida de peso; el trastorno obsesivo compulsivo tiene obsesiones y compulsiones. Se evalúan siempre el riesgo suicida, el hipotiroidismo y otras causas médicas, y se cuantifica la gravedad con el PHQ-9 (5-9 leve, 10-14 moderada, 15-19 moderadamente grave, 20 o más grave). El tratamiento combina ISRS y psicoterapia, y la respuesta se espera en 4 a 6 semanas. Perla clínica: el empeoramiento matutino y la pérdida de peso apuntan a depresión melancólica.",
  f=DSM + "; " + KS + "; " + HAR)

Q(a="psiquiatria", cat="Violencia familiar", tema="Comunicación en la violencia de pareja", año=2019, ext=False,
  e="¿Por qué se caracterizan los problemas de violencia en la pareja?",
  o=["Extrovertido.", "Comunicaciones negativas.", "Expectativas reales.", "Hijos adolescentes.", "Satisfacción laboral."], k="B",
  c="Los patrones de interacción de las parejas violentas se caracterizan por comunicación negativa: críticas constantes, desprecio, actitud defensiva, hostilidad, ambigüedad, ocultamiento de información y descalificación de las opiniones del otro. Esa comunicación deteriorada incrementa la tensión y favorece el ciclo de la violencia descrito por Walker, con una fase de acumulación de tensión, un episodio agudo de agresión y una fase de reconciliación o luna de miel que mantiene a la víctima en la relación. Las opciones restantes describen factores protectores o irrelevantes: unas expectativas realistas y la satisfacción laboral disminuyen el conflicto, ser extrovertido no es un rasgo asociado a la agresión y tener hijos adolescentes no define a la pareja violenta. Se reconocen otros factores de riesgo, como el consumo de alcohol, los celos patológicos, la desigualdad de poder y la violencia vivida en la infancia. A escala mundial, cerca de una de cada tres mujeres sufre violencia física o sexual de pareja a lo largo de su vida según la OMS. El abordaje exige tamizar con preguntas directas, evaluar el riesgo, elaborar un plan de seguridad y derivar. Perla clínica: la terapia de pareja está contraindicada mientras exista violencia activa.",
  f="OMS, directrices clínicas y de políticas sobre la respuesta a la violencia de pareja y la violencia sexual contra la mujer (2013); " + KS,
  nota="El enunciado del libro es ambiguo; se interpreta como «qué caracteriza a las parejas con violencia».")

Q(a="psiquiatria", cat="Trastornos del ánimo", tema="Depresión en el adolescente: irritabilidad", año=2018, ext=False,
  e="¿Qué caracteriza al síndrome depresivo en adolescentes?",
  o=["Hiperfagia.", "Insomnio.", "Alucinaciones.", "Verborrea.", "Irritabilidad."], k="E",
  c="El DSM-5-TR (2022) permite que en niños y adolescentes el ánimo depresivo se exprese como irritabilidad, de modo que este es el rasgo más característico y a veces el síntoma principal, con enfados fáciles, hostilidad, rebeldía y quejas somáticas como cefalea o dolor abdominal, junto con descenso del rendimiento escolar, aislamiento y anhedonia. Los criterios son los mismos del adulto, con una duración de dos semanas para el episodio mayor y un año, en lugar de dos, para el trastorno depresivo persistente. En el adolescente son más frecuentes que en el adulto la hipersomnia y la hiperfagia, pero estos síntomas no definen el cuadro; el insomnio es común en todas las edades; las alucinaciones solo aparecen en las formas psicóticas, y la verborrea es propia de la manía o hipomanía, lo que obliga a descartar un trastorno bipolar. Las guías GLAD-PC (2018) recomiendan tamizar con el PHQ-A a partir de los 12 años, vigilar siempre el riesgo suicida y, en depresión leve, ofrecer apoyo activo; en depresión moderada o grave se indica psicoterapia (cognitivo-conductual o interpersonal) y fluoxetina como antidepresivo de primera línea, con seguimiento estrecho por la advertencia de riesgo suicida en menores de 25 años. Perla clínica: el suicidio es una de las principales causas de muerte en la adolescencia.",
  f=GLAD + "; " + DSM + "; " + KS)

Q(a="psiquiatria", cat="Trastornos del ánimo", tema="Depresión mayor con insomnio terminal", año=2019, ext=False,
  e="Abogado de 45 años, consulta por presentar hace 2 meses tristeza, apatía, pérdida de interés por su trabajo y sus familiares, «prefiere estar solo». Constantemente se muestra irritable, con incapacidad para concentrarse. Además, hiporexia, pérdida de peso e insomnio de segunda mitad. ¿Cuál es el trastorno más probable?",
  o=["Obsesivo-compulsivo.", "Ansiedad generalizada.", "Orgánico cerebral.", "Estrés laboral.", "Depresión mayor."], k="E",
  c="Dos meses de ánimo triste, anhedonia, retraimiento, irritabilidad, dificultad de concentración, hiporexia con pérdida de peso e insomnio con despertar precoz (la mitad final de la noche) cumplen con holgura los criterios de episodio depresivo mayor del DSM-5-TR (2022): cinco síntomas durante al menos dos semanas con deterioro del funcionamiento. El despertar temprano, junto con la pérdida de apetito y de peso, es característico de la depresión melancólica, mientras que el insomnio de conciliación se ve más en la ansiedad. El trastorno de ansiedad generalizada requiere preocupación excesiva durante al menos seis meses y tensión muscular; el obsesivo-compulsivo implica obsesiones y compulsiones; el estrés laboral es una reacción adaptativa que no alcanza tal número de síntomas, y el trastorno orgánico cerebral se considera solo si hay déficit cognitivo, signos neurológicos o una causa médica identificada. Aun así, antes de confirmar el diagnóstico se descartan hipotiroidismo, anemia, déficit de vitamina B12, consumo de alcohol y fármacos. Se mide la gravedad con el PHQ-9 y se evalúa la ideación suicida; el tratamiento de elección es un ISRS con psicoterapia, que se mantiene de seis a doce meses tras la remisión. Perla clínica: en el varón deprimido la irritabilidad y el abuso de alcohol pueden enmascarar el cuadro.",
  f=DSM + "; " + KS + "; " + HAR)

Q(a="psiquiatria", cat="Trastornos de la conducta alimentaria", tema="Anorexia nerviosa subtipo purgativo", año=2019, ext=False,
  e="Adolescente de 15 años que presenta baja de peso, lanugo, interrupción de la menstruación, lesión del esmalte dental y callosidad en dorso de los dedos. Acude a consulta muy abrigada. ¿Cuál es el diagnóstico probable?",
  o=["Anorexia nervosa.", "Bulimia.", "Psicosis.", "Depresión.", "Hipertiroidismo."], k="A",
  c="La anorexia nerviosa se define por restricción de la ingesta que conduce a un peso significativamente bajo, miedo intenso a engordar o conductas que impiden ganar peso, y alteración de la imagen corporal. El DSM-5-TR (2022) ya no exige amenorrea, pero esta es frecuente, junto con lanugo, bradicardia, hipotermia, intolerancia al frío (la paciente va muy abrigada), hipotensión y acrocianosis. La erosión del esmalte y las callosidades en el dorso de los dedos (signo de Russell) revelan vómito autoprovocado y por tanto el subtipo con atracones o purgas; aun así, el bajo peso con lanugo y amenorrea mantiene el diagnóstico de anorexia, y no de bulimia, en la que el peso es normal o elevado. La psicosis y la depresión pueden reducir el apetito, pero no explican el cuadro físico ni el patrón de purga; el hipertiroidismo cursa con pérdida de peso, pero con hiperfagia, intolerancia al calor, taquicardia y bocio. La gravedad en adultos se clasifica por IMC: leve 17 o más, moderada 16-16,99, grave 15-15,99 y extrema menos de 15; en adolescentes se usan percentiles. Se hospitaliza si hay bradicardia marcada, hipotensión, hipopotasemia o inestabilidad, y se vigila el síndrome de realimentación. El tratamiento de primera línea en adolescentes es la terapia basada en la familia, según la guía de la APA (2023).",
  f="APA, guía de práctica para el tratamiento de los trastornos de la conducta alimentaria (Am J Psychiatry 2023); " + DSM + "; " + KS,
  nota="Redacción del libro: «lesión del esmalte» y «callosidad en dorso de los dedos» orientan a purgas; la clave A del libro se mantiene por el bajo peso, el lanugo y la amenorrea.")

Q(a="psiquiatria", cat="Trastornos del ánimo", tema="Depresión mayor del adolescente con ideación suicida", año=2019, ext=False,
  e="Paciente de 15 años, desde hace 30 días presenta irritabilidad, pérdida de interés en las actividades, sensación de inutilidad, alteración del sueño y pensamientos suicidas. ¿Cuál es el diagnóstico probable?",
  o=["Distimia.", "Trastorno bipolar.", "Ansiedad.", "Depresión mayor.", "Autismo."], k="D",
  c="Un adolescente con un mes de irritabilidad, anhedonia, sentimientos de inutilidad, alteración del sueño e ideación suicida cumple criterios de episodio depresivo mayor del DSM-5-TR (2022): al menos dos semanas de cinco síntomas con ánimo deprimido o irritable, o pérdida de interés. La distimia requiere un año de síntomas en los adolescentes y suele ser menos intensa; el trastorno bipolar exige haber tenido un episodio maniaco o hipomaniaco previo, por lo que se pregunta siempre por periodos de euforia, grandiosidad y disminución de la necesidad de sueño antes de iniciar un antidepresivo; la ansiedad produce preocupación y síntomas autonómicos y no cuenta con ideación de inutilidad; el autismo es un trastorno del neurodesarrollo que se manifiesta desde la primera infancia con déficit de comunicación social y conductas repetitivas. Lo más urgente es estimar el riesgo suicida (ideación, plan, intento previo, acceso a medios) y, si es alto, hospitalizar; en los demás casos se establece un plan de seguridad. Según las guías GLAD-PC (2018), la depresión moderada o grave se trata con psicoterapia cognitivo-conductual o interpersonal y fluoxetina, con vigilancia semanal del riesgo suicida durante el primer mes. Perla clínica: preguntar por el suicidio no lo induce; lo previene al facilitar la detección.",
  f=GLAD + "; " + DSM + "; " + KS)

Q(a="psiquiatria", cat="Trastornos de la conducta alimentaria", tema="Bulimia nerviosa", año=2019, ext=False,
  e="Adolescente de 14 años que los padres advierten que consume grandes cantidades de alimento, encuentran laxantes en su cuarto y la adolescente se queja que no puede controlar el apetito. ¿Cuál es el diagnóstico probable?",
  o=["Fobia a ganar peso.", "Trastorno bipolar.", "Ansiedad generalizada.", "Pica.", "Bulimia nervosa."], k="E",
  c="La bulimia nerviosa se define, según el DSM-5-TR (2022), por atracones recurrentes (ingesta de una cantidad claramente mayor a la habitual en un periodo de dos horas con sensación de pérdida de control), conductas compensatorias inapropiadas para evitar el aumento de peso (vómito autoprovocado, laxantes, diuréticos, ayuno, ejercicio excesivo), una frecuencia mínima de una vez por semana durante tres meses y una autoevaluación indebidamente influida por el peso y la silueta. El peso suele ser normal, lo que diferencia el cuadro de la anorexia. El hallazgo de laxantes y la pérdida de control del apetito completan el cuadro típico. Los datos físicos incluyen hipertrofia parotídea, erosión dental, signo de Russell, hipopotasemia con alcalosis metabólica hipoclorémica, arritmias y, a veces, desgarro de Mallory-Weiss. La pica es la ingestión persistente de sustancias no nutritivas como tierra o hielo; la «fobia a ganar peso» no es una categoría diagnóstica, sino un síntoma; el trastorno bipolar y la ansiedad generalizada no explican las conductas compensatorias. El tratamiento combina terapia cognitivo-conductual y, en adultos y adolescentes mayores, fluoxetina a dosis altas (60 mg diarios), evitando el bupropión por el riesgo de convulsiones. Perla clínica: se solicitan electrolitos y electrocardiograma ante la purga.",
  f="APA, guía de práctica para el tratamiento de los trastornos de la conducta alimentaria (Am J Psychiatry 2023); " + DSM + "; " + KS)

Q(a="reumatologia", cat="Osteoporosis", tema="Bioquímica en la osteoporosis", año=2015, ext=True,
  e="¿Cuál de los siguientes patrones bioquímicos se encuentra en la osteoporosis?",
  o=["Calcemia elevada, fosforemia normal y fosfatasa alcalina elevada.", "Calcemia elevada, fosforemia normal y fosfatasa alcalina normal.", "Calcemia normal, fosforemia baja y fosfatasa alcalina normal.", "Calcemia elevada, fosforemia baja y fosfatasa alcalina baja.", "Calcemia normal, fosforemia normal y fosfatasa alcalina normal."], k="E",
  c="La osteoporosis es una enfermedad esquelética sistémica con disminución de la masa ósea y deterioro de la microarquitectura, que aumenta la fragilidad y el riesgo de fractura. Por resorción por osteoclastos que supera a la formación por osteoblastos, se pierde hueso sin alterar la mineralización de la matriz restante, por lo que el calcio, el fósforo y la fosfatasa alcalina séricos son normales; solo la fosfatasa alcalina puede subir de forma transitoria tras una fractura reciente. Esta normalidad permite distinguirla de otras osteopatías: en la osteomalacia hay calcio normal o bajo, fósforo bajo y fosfatasa alcalina elevada, por déficit de mineralización; en el hiperparatiroidismo primario hay hipercalcemia con hipofosfatemia; en la enfermedad de Paget la fosfatasa alcalina es muy alta con calcio y fósforo normales, y en el mieloma múltiple o las metástasis puede haber hipercalcemia. Ante una osteoporosis se descartan causas secundarias con calcio, fósforo, creatinina, 25-hidroxivitamina D, PTH, TSH, hemograma y calciuria de 24 horas. Los marcadores de recambio óseo (CTX, P1NP) sirven para monitorizar el tratamiento, no para diagnosticar. Perla clínica: una osteoporosis con laboratorio alterado es una osteoporosis secundaria hasta demostrar lo contrario.",
  f=OSTEO + "; " + HAR + "; Canadá, guía de práctica clínica de osteoporosis y prevención de fracturas, actualización 2023 (CMAJ 2023)",
  nota="Las opciones B a D están dañadas por el OCR; se reconstruyeron como distractores plausibles. La clave E (todo normal) coincide con el libro.")

Q(a="reumatologia", cat="Osteoporosis", tema="Confirmación diagnóstica de osteoporosis: densitometría", año=2016, ext=False,
  e="Mujer de 65 años, consulta por dolor en columna dorso lumbar de dos años de evolución. Se plantea el diagnóstico de osteoporosis. ¿Qué examen solicita para confirmar el diagnóstico?",
  o=["Densitometría ósea.", "Resonancia magnética con secuencia espectroscópica.", "Resonancia magnética con secuencia de difusión.", "Resonancia magnética funcional.", "Tomografía axial computarizada ósea."], k="A",
  c="La prueba estándar para diagnosticar osteoporosis y estimar el riesgo de fractura es la absorciometría de rayos X de energía dual (DXA) de columna lumbar y cadera, con el índice T como medida: según la OMS, un valor de -2,5 o menor indica osteoporosis, entre -1 y -2,5 osteopenia o baja masa ósea, y de -1 o más normalidad. En mujeres premenopáusicas y varones jóvenes se usa el índice Z. Una fractura por fragilidad de cadera o vertebral también establece el diagnóstico clínico aun con DXA no osteoporótica. El USPSTF (2025) recomienda tamizar a todas las mujeres de 65 años o más y a las posmenopáusicas más jóvenes con riesgo aumentado. Las resonancias y la tomografía no miden la densidad mineral de manera estandarizada ni se usan para el diagnóstico; sin embargo, ante un dolor dorsolumbar de dos años conviene una radiografía lateral de columna dorsal y lumbar, o la evaluación vertebral por DXA, para detectar fracturas por aplastamiento, y la resonancia se reserva para sospecha de metástasis, mieloma o compresión neurológica. Se calcula el riesgo a 10 años con FRAX y, en mujeres con osteoporosis, el tratamiento de primera línea son los bisfosfonatos orales (alendronato) junto con calcio y vitamina D. Perla clínica: la fractura vertebral previa es el principal predictor de nuevas fracturas.",
  f="USPSTF, tamizaje de osteoporosis para prevenir fracturas (JAMA 2025); " + OSTEO + "; Canadá, guía de práctica clínica de osteoporosis y prevención de fracturas, actualización 2023 (CMAJ 2023)")

Q(a="reumatologia", cat="Lupus", tema="Clasificación histológica de la nefritis lúpica: clase V", año=2016, ext=False,
  e="Según la clasificación histológica de la nefritis lúpica, ¿en qué clase se ubica la nefritis membranosa?",
  o=["V.", "III.", "IV.", "VI.", "II."], k="A",
  c="La clasificación ISN/RPS de la nefritis lúpica reconoce seis clases: I, mesangial mínima; II, proliferativa mesangial; III, focal (menos del 50 % de los glomérulos); IV, difusa (50 % o más), segmentaria o global; V, membranosa, con depósitos inmunes subepiteliales y engrosamiento de la membrana basal, y VI, esclerosante avanzada (más del 90 % de glomérulos esclerosados). La clase V se manifiesta por proteinuria en rango nefrótico, a menudo con sedimento poco activo, y se asocia a mayor riesgo trombótico, por lo que se vigila la trombosis de la vena renal. Las clases III y IV son las proliferativas, con hematuria, cilindros eritrocitarios, hipocomplementemia, anti-ADN elevado y deterioro de la función renal, y requieren inducción con glucocorticoides más micofenolato o ciclofosfamida; las guías KDIGO (2024) y ACR (2024) recomiendan terapia combinada con un tercer agente (belimumab o un inhibidor de calcineurina como voclosporina). Las clases I y II suelen manejarse con hidroxicloroquina y control, y la clase VI no responde a inmunosupresión y progresa a diálisis. La biopsia se indica ante proteinuria persistente mayor de 0,5 g/24 horas, hematuria glomerular o deterioro renal. Perla clínica: todo paciente con lupus recibe hidroxicloroquina, salvo contraindicación.",
  f="KDIGO, guía de práctica clínica de nefritis lúpica (Kidney Int 2024); ACR, guía de tamizaje, tratamiento y manejo de la nefritis lúpica 2024 (Arthritis Rheumatol 2025); " + HAR)

Q(a="reumatologia", cat="Artritis reumatoide", tema="FARME biológico anti-TNF: infliximab", año=2016, ext=False,
  e="¿Cuál de los siguientes fármacos antirreumatoideos modificadores de enfermedad (FARME) actúa como antagonista del factor de necrosis tumoral alfa (TNF-α)?",
  o=["Infliximab.", "Micofenolato mofetilo.", "Leflunomida.", "Rituximab.", "Abatacept."], k="A",
  c="El infliximab es un anticuerpo monoclonal quimérico dirigido contra el TNF-α, igual que adalimumab, golimumab y certolizumab pegol, mientras que etanercept es una proteína de fusión receptor soluble del TNF-Fc. Estos agentes son FARME biológicos que se usan en artritis reumatoide, espondiloartritis, artritis psoriásica y enfermedad inflamatoria intestinal. Las demás opciones tienen otros mecanismos: el micofenolato inhibe la inosina monofosfato deshidrogenasa y bloquea la proliferación de linfocitos (se usa en nefritis lúpica y trasplante); la leflunomida inhibe la dihidroorotato deshidrogenasa y es un FARME sintético convencional; el rituximab es un anticuerpo anti-CD20 que depleta linfocitos B, y el abatacept (CTLA4-Ig) bloquea la coestimulación CD80/CD86 con CD28 del linfocito T. La guía ACR 2021 mantiene el metotrexato como tratamiento inicial y agrega un biológico o un inhibidor de JAK si no se alcanza la meta con el esquema convencional. Antes de iniciar un anti-TNF se descartan tuberculosis latente (en Perú según la NTS 221-MINSA/DGIESP-2024), hepatitis B y C, e infecciones activas, y están contraindicados en insuficiencia cardiaca grave, esclerosis múltiple y neoplasia reciente. Perla clínica: el anti-TNF puede reactivar la tuberculosis, sobre todo con infliximab.",
  f="ACR, guía de tratamiento de la artritis reumatoide (Arthritis Care Res 2021); " + HAR + "; MINSA, NTS 221-MINSA/DGIESP-2024 (prevención y control de la tuberculosis)")

Q(a="reumatologia", cat="Osteoporosis", tema="Criterio OMS de osteoporosis en mujeres posmenopáusicas", año=2017, ext=False,
  e="¿Cuál es el criterio diagnóstico de osteoporosis según la OMS en mujeres mayores de 65 años?",
  o=["Densitometría ósea inferior a -2,5 DE en cualquier localización.", "Fracturas patológicas en cadera.", "Acuñamiento anterior de las vértebras.", "Fracturas patológicas en muñeca y cadera.", "Densitometría ósea inferior a -1,5 DE en cuello de fémur."], k="A",
  c="El criterio densitométrico de la OMS, aplicado a mujeres posmenopáusicas y varones de 50 años o más, define osteoporosis como un índice T de -2,5 desviaciones estándar o menor en columna lumbar, cuello femoral o cadera total, medido por DXA y comparado con el adulto joven sano; la osteopenia (baja masa ósea) corresponde a un índice T entre -1,0 y -2,5, y lo normal es -1,0 o más. En sentido estricto el sitio de medición son esas regiones centrales, no «cualquier localización», pero entre las opciones esta es la que mejor refleja el criterio. El umbral de -1,5 de la opción E no existe en la clasificación. Las opciones de fractura (cadera, vértebras) son criterios clínicos adicionales de las guías actuales: una fractura de cadera o vertebral por fragilidad bastan para diagnosticar osteoporosis, pero la fractura de muñeca aislada no lo hace por sí sola, y no corresponden al criterio de la OMS por DXA. Después del diagnóstico se estima el riesgo con FRAX y se trata si el riesgo a 10 años es alto, con bisfosfonatos como primera línea, denosumab o teriparatida en riesgo muy alto, más calcio, vitamina D y ejercicio de carga. Perla clínica: el índice T no se aplica en niños ni en mujeres premenopáusicas, en quienes se usa el índice Z.",
  f=OSTEO + "; USPSTF, tamizaje de osteoporosis para prevenir fracturas (JAMA 2025); Canadá, guía de práctica clínica de osteoporosis y prevención de fracturas, actualización 2023 (CMAJ 2023)",
  nota="El libro afirma que la osteopenia va de -1,5 a -2,5 (Kumar); el rango OMS es -1,0 a -2,5. La clave A se mantiene.")
